from collections import deque

def transform(g):
    h,w=len(g),len(g[0])
    cols={c for r in g for c in r}
    # border color = color forming enclosing structures; background = most common other
    from collections import Counter
    cnt=Counter(c for r in g for c in r)
    # try each candidate border color; fill non-border unreachable cells with 4
    # pick border color as the one with max color > background? use: background=most common
    bg=cnt.most_common(1)[0][0]
    res=[r[:] for r in g]
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]!=None: q.append((i,j)); seen[i][j]=True
    for j in range(w):
        for i in (0,h-1):
            if not seen[i][j]: q.append((i,j)); seen[i][j]=True
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and not seen[a][b] and g[a][b]==bg:
                seen[a][b]=True; q.append((a,b))
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and not seen[i][j]:
                res[i][j]=4
    return res

